import { Order, OrderItem } from '../domain/Order';
import { OrderRepository, ProductRepository } from '../domain/Repository';
import { CreateOrderRequest, CreateOrderResponse } from './DTOs';

export class PlaceOrderUseCase {
  constructor(
    private orderRepository: OrderRepository,
    private productRepository: ProductRepository
  ) {}

  execute(request: CreateOrderRequest): CreateOrderResponse {
    const { customerId, items } = request;

    if (!customerId) throw new Error('Customer ID is required');
    if (items.length === 0) throw new Error('Order must contain at least one item');

    for (const item of items) {
      const product = this.productRepository.findById(item.productId);
      if (!product) throw new Error(`Product ${item.productId} not found`);
      if (product.getStock() < item.quantity) {
        throw new Error(`Insufficient stock for product ${item.productId}`);
      }
    }

    for (const item of items) {
      const product = this.productRepository.findById(item.productId)!;
      product.reserve(item.quantity);
    }

    const orderItems = items.map(item => new OrderItem(item.productId, item.quantity));
    const order = new Order(`order-${Date.now()}`, customerId, orderItems);
    this.orderRepository.save(order);

    return this.toResponse(order);
  }

  private toResponse(order: Order): CreateOrderResponse {
    return {
      id: order.id,
      customerId: order.customerId,
      state: order.getState(),
      items: order.items.map(item => ({
        productId: item.productId,
        quantity: item.quantity
      })),
      createdAt: order.createdAt.toISOString()
    };
  }
}

